uint64_t rookMasks[64];
uint64_t bishopMasks[64];
int rookShifts[64];
int bishopShifts[64];
int rookOffsets[64];
int bishopOffsets[64];
uint64_t bishopTable[bishopTableSize];

#if ENGINE_ROOK_BACKEND == ENGINE_ROOK_COMPUTED
uint64_t rookTable[rookTableSize];
#endif

static const int rookDirections[4][2] = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};
static const int bishopDirections[4][2] = {{-1, -1}, {-1, 1}, {1, -1}, {1, 1}};

static bool onBoard(int row, int col) {
    return row >= 0 && row < 8 && col >= 0 && col < 8;
}

//squares whose occupancy can change the attack set: every ray square except the last one before the edge,
//since a piece on the edge square can't block anything beyond it
static uint64_t relevantBlockerMask(int square, const int directions[4][2]) {
    uint64_t mask = 0;
    for(int dir = 0; dir < 4; dir++) {
        int row = square / 8 + directions[dir][0];
        int col = square % 8 + directions[dir][1];
        while(onBoard(row + directions[dir][0], col + directions[dir][1])) {
            mask |= squareBit(row * 8 + col);
            row += directions[dir][0];
            col += directions[dir][1];
        }
    }
    return mask;
}

static uint64_t slowAttacks(int square, uint64_t occupied, const int directions[4][2]) {
    uint64_t attacks = 0;
    for(int dir = 0; dir < 4; dir++) {
        int row = square / 8 + directions[dir][0];
        int col = square % 8 + directions[dir][1];
        while(onBoard(row, col)) {
            uint64_t target = squareBit(row * 8 + col);
            attacks |= target;
            if((occupied & target) != 0) break;
            row += directions[dir][0];
            col += directions[dir][1];
        }
    }
    return attacks;
}

uint64_t slowRookAttacks(int square, uint64_t occupied) {
    return slowAttacks(square, occupied, rookDirections);
}

uint64_t slowBishopAttacks(int square, uint64_t occupied) {
    return slowAttacks(square, occupied, bishopDirections);
}

//fills masks/shifts/offsets and returns the total table size needed for this piece type
static int initMasks(uint64_t* masks, int* shifts, int* offsets, const int directions[4][2]) {
    int offset = 0;
    for(int square = 0; square < 64; square++) {
        masks[square] = relevantBlockerMask(square, directions);
        int bits = popcount(masks[square]);
        shifts[square] = 64 - bits;
        offsets[square] = offset;
        offset += 1 << bits;
    }
    return offset;
}

static void fillTable(uint64_t* table, const uint64_t* masks, const uint64_t* magics, const int* shifts,
                      const int* offsets, const int directions[4][2]) {
    for(int square = 0; square < 64; square++) {
        uint64_t mask = masks[square];
        //Carry-Rippler: steps through every subset of `mask`, ending when it wraps back to 0
        uint64_t subset = 0;
        do {
            int index = (int) ((subset * magics[square]) >> shifts[square]);
            table[offsets[square] + index] = slowAttacks(square, subset, directions);
            subset = (subset - mask) & mask;
        } while(subset != 0);
    }
}

void buildRookTable(uint64_t* table) {
    fillTable(table, rookMasks, rookMagics, rookShifts, rookOffsets, rookDirections);
}

void init() {
    initMasks(rookMasks, rookShifts, rookOffsets, rookDirections);
    initMasks(bishopMasks, bishopShifts, bishopOffsets, bishopDirections);
    fillTable(bishopTable, bishopMasks, bishopMagics, bishopShifts, bishopOffsets, bishopDirections);
#if ENGINE_ROOK_BACKEND == ENGINE_ROOK_COMPUTED
    buildRookTable(rookTable);
#endif
}

